import {useState, useEffect, use} from 'react';

export default function OwnedTickets() {
    const [tickets, setTickets] = useState([]);
    const [showModal, setShowModal] = useState(false);
    const [currentTicket, setCurrentTicket] = useState(null);
    const token = localStorage.getItem("token");

    useEffect(() => {
        async function fetchTickets() {
            try {
                const response = await fetch("http://localhost:3001/ownedTickets", {
                    headers: {
                        "Authorization": `Bearer ${token}`
                    }
                });

                const data = await response.json();

                if (!response.ok) {
                    alert(`Sikertelen lekérdezés: ${data.message}`);
                } else {
                    setTickets(data.tickets);
                }
            } catch (err) {
                console.log(err);
                alert("Hiba történt a hibajegyek lekérése közben.");
            }
        }

        fetchTickets();
    }, [token]);

    const handleEdit = (ticket) => {
        setCurrentTicket(ticket);
        setShowModal(true);
    };

    const handleChange = (e) => {
        setCurrentTicket({
            ...currentTicket,
            [e.target.name]: e.target.value,
        });
    };

  async function handleSave() {
        setShowModal(false);

        const response = fetch(`http://localhost:3001/tickets/${currentTicket.id}`, {
            method: "PUT",
            headers: {
                "Content-Type": "application/json",
                "Authorization": `Bearer ${token}`,
            },
            body: JSON.stringify(currentTicket),
        });

        const data = await response.json();

        if (!response.ok) {
            alert(`Sikertelen mentés: ${data.message}`);
        } else {
            alert("Sikeres mentés");

        }

    };

    return (
        <div className="container">
            <div className="card text-center">
            {tickets ? tickets.map(tickets => {
                return (
                <div className="card">
                    <div className="card-header">{tickets.urgentid}</div>
                    <div className="card-body">
                        <h3 className="card-title">{tickets.title}</h3>
                        <h6 className="card-title">{tickets.place}</h6>
                        <p className="card-text">{tickets.description}</p>
                        <h6 className="card-title">{tickets.userid}</h6>
                        <a href="#" className="btn btn-success me-2">Kiosztás</a>
                        <a href="#" className="btn btn-primary me-2" onClick={() => handleEdit(tickets)}>Módosítás</a>
                        <a href="#" className="btn btn-danger">Törlés</a>
                    </div>
                    <div className="card-footer text-body-secondary">{tickets.formatted_created_at}</div>
                </div>
            )
            }) : (<p>Nincsenek hibajegyeid.</p>)}
        </div>

          {/* Modal */}
            {showModal && currentTicket && (
                <div className="modal show d-block" tabIndex="-1">
                    <div className="modal-dialog">
                        <div className="modal-content">
                            <div className="modal-header">
                                <h5 className="modal-title">Ticket módosítása</h5>
                                <button type="button" className="btn-close" onClick={() => setShowModal(false)}></button>
                            </div>
                            <div className="modal-body">
                                <div className="mb-3">
                                    <label className="form-label">Cím</label>
                                    <input
                                        type="text"
                                        className="form-control"
                                        name="title"
                                        value={currentTicket.title}
                                        onChange={handleChange}
                                    />
                                </div>
                                <div className="mb-3">
                                    <label className="form-label">Helyszín</label>
                                    <input
                                        type="text"
                                        className="form-control"
                                        name="place"
                                        value={currentTicket.place}
                                        onChange={handleChange}
                                    />
                                </div>
                                <div className="mb-3">
                                    <label className="form-label">Leírás</label>
                                    <textarea
                                        className="form-control"
                                        name="description"
                                        value={currentTicket.description}
                                        onChange={handleChange}
                                    ></textarea>
                                </div>
                            </div>
                            <div className="modal-footer">
                                <button className="btn btn-secondary" onClick={() => setShowModal(false)}>Mégse</button>
                                <button className="btn btn-primary" onClick={handleSave}>Mentés</button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}
